import{z as A,x as B,o as r,c as p,q as o,j as n,D as E,d as e,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"抽象解释","description":"","frontmatter":{"title":"抽象解释","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abstract-interpretation.md","filePath":"cs/abstract-interpretation.md","lastUpdated":1791063341000}'),d={name:"cs/abstract-interpretation.md"};function u(m,a,D,C,f,h){const s=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="抽象解释" tabindex="-1">抽象解释 <a class="header-anchor" href="#抽象解释" aria-label="Permalink to &quot;抽象解释&quot;">​</a></h1><div class="epigraph"><p>在抽象域上模拟程序：具体状态集被 Galois 连接压成格上的元素。不动点给出不变量，服务于类型之外的静态分析。</p><footer>—— 据 Cousot and Cousot, Abstract Interpretation, 1977；龙书数据流章对照；[Knaster–Tarski](/cs/knaster-tarski-fixpoint) 整理</footer></div><p>上一课<a href="/cs/denotational-semantics">指称</a>给出理想含义，太大算不了。缺口是<strong>可靠近似</strong>：区间、符号、符号执行的亲戚——抽象解释。主干<a href="/cs/dataflow-liveness">数据流</a>是同一家族的方程；本课钉 Galois 连接与加宽，不把所有抽象域列成百科。类型系统是一种抽象（类型是抽象值），但本课面向分析器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>具体收集语义：每个程序点的可达状态集。无限。抽象：区间 \\([L,H]\\)、符号、八边形。Galois：\\((\\alpha,\\gamma)\\) 保证抽象转移 \\(\\nabla\\) 可靠（不漏具体行为）。缺口是<strong>可靠与精度的权衡</strong>，不是 SOS 的一步规则。</p><p>加宽（widening）强迫升链收敛，可能损失精度；变窄再收回一点。循环必须处理——后课自然循环识别与此衔接。</p><h3 id="可靠不是完备" tabindex="-1">可靠不是完备 <a class="header-anchor" href="#可靠不是完备" aria-label="Permalink to &quot;可靠不是完备&quot;">​</a></h3><p>分析可说「可能别名」而其实没有——假阳性。完备相对选定抽象域：域表达不了的性质永远未知。不要把「未报错」当程序无错（若目标是找 bug，漏报更危险，方向会调）。</p><p><span class="marginnote">Cousot–Cousot 1977（POPL）。龙书把到达定值、可用表达式写成数据流，是有限高度格上的抽象解释特例。本课不写 Astrée 的全部域。</span></p><p><span class="marginnote">直觉类比：抽象解释像用一块「只能显示区间」的仪表看程序——变量的取值不再是具体的数，而是「在 0 到 100 之间」。仪表读数必须罩住真实值（可靠），可以偏宽（假阳性），但绝不能偏窄，否则分析结论就在骗人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选抽象域与转移。解 \\(X=F(X)\\) 用迭代+加宽。用于：值范围、空指针、常量（后课常量传播是平坦域）。类型推导也可看成抽象：合一是精确的，子类型是近似方向。</p>',12)),(r(),n(l,null,{default:E(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CON%5B%22%E5%85%B7%E4%BD%93%E7%8A%B6%E6%80%81%E9%9B%86%22%5D%20--%3E%20A%5B%22%CE%B1%20%E6%8A%BD%E8%B1%A1%22%5D%0A%20%20A%20--%3E%20FIX%5B%22%E6%A0%BC%E4%B8%8A%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20FIX%20--%3E%20G%5B%22%CE%B3%20%E5%85%B7%E4%BD%93%E5%8C%96%20%E2%8A%82%20%E5%8F%AF%E9%9D%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("与效应、区域：可当抽象域的分量。与 SMT：抽象解释给不变量，SMT 可在路径上精化，"),t("a",{href:"/cs/smt-solver"},"SMT"),e(" 已见。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"Galois 连接保证可靠；若不要求连接，至少要 sound transformer（over-approx）。并行与弱内存使具体语义本身难写，分析更保守。",-1)),a[6]||(a[6]=t("p",null,"不要用抽象解释替代线性/借用：后者是语言纪律，前者是对已写程序的近似。",-1)),a[7]||(a[7]=t("p",null,"第一张图画的是 Galois 连接的静态骨架；这张图回答第二个问题：循环里变量区间一路上涨时，加宽怎么强迫迭代在有限步内停下来，变窄再收回多少精度。",-1)),(r(),n(l,null,{default:E(()=>[i(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20IT%5B%22%E8%BF%AD%E4%BB%A3%E5%8C%BA%E9%97%B4%E5%88%86%E6%9E%90%22%5D%20--%3E%20UP%5B%22%E4%B8%8A%E7%95%8C%E4%B8%80%E6%AD%A5%E6%AD%A5%E6%B6%A8%22%5D%0A%20%20UP%20--%3E%20CHAIN%5B%22%E5%8C%BA%E9%97%B4%200%20%E5%88%B0%200%EF%BC%8C%E5%86%8D%200%20%E5%88%B0%201%E3%80%810%20%E5%88%B0%202%E2%80%A6%E2%80%A6%22%5D%0A%20%20CHAIN%20--%3E%20DIVERGE%7B%22%E4%B8%8A%E7%95%8C%E8%BF%98%E5%9C%A8%E6%B6%A8%EF%BC%9F%22%7D%0A%20%20DIVERGE%20--%3E%7C%22%E6%98%AF%22%7C%20WID%5B%22%E5%8A%A0%E5%AE%BD%EF%BC%9A%E4%B8%80%E6%AD%A5%E8%B7%B3%E5%88%B0%E6%97%A0%E7%A9%B7%22%5D%0A%20%20WID%20--%3E%20CONV%5B%22%E6%9C%89%E9%99%90%E6%AD%A5%E6%94%B6%E6%95%9B%E5%88%B0%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20CONV%20--%3E%20NAR%5B%22%E5%8F%98%E7%AA%84%EF%BC%9A%E7%94%A8%E5%BE%AA%E7%8E%AF%E6%9D%A1%E4%BB%B6%E6%94%B6%E5%9B%9E%22%5D%0A%20%20NAR%20--%3E%20RES%5B%22%E5%BE%97%E5%88%B0%200%20%E5%88%B0%20100%20%E4%B8%80%E7%B1%BB%E7%9A%84%E5%AE%9E%E7%94%A8%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：分析 for 循环里的计数器 i 时，区间从 [0,0] 涨到 [0,1]、[0,2]……永不收敛。加宽的规矩是看到上界连涨就一步跳到 [0,+无穷) 保住收敛性；随后用循环条件 i 小于 100 变窄，收回成 [0,100]。不加宽，迭代永远算不完。</span></p><p><span class="marginnote">常见误区：初学者容易以为「报警就一定是 bug、没报就一定安全」。对「证明程序正确」方向的分析，报警只是可能有问题（允许假阳性），不报才可信；换成「找 bug」工具，取舍会反过来——漏报才是大忌。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现完整区间分析器。后课默认：数据流优化是有限格上的 AI。下一课空与 Option：把「可能空」从分析变成类型。</p><p>也不把机器学习当抽象域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抽象解释：Galois + 格不动点，可靠近似收集语义。</li><li>数据流是特例；加宽服务循环。</li><li>可靠≠完备；假阳性与漏报取决于问题方向。</li><li>出处：Cousot and Cousot, 1977；对照龙书数据流；Knaster–Tarski。</li></ul>',7))])}const T=A(d,[["render",u]]);export{b as __pageData,T as default};
